"use client"

import * as React from "react"
import { cn } from "@/lib/rillmark-utils"
import { useFieldControl } from "@/components/ui/field"

export function Input({ className, type = "text", ...props }: React.ComponentProps<"input">) {
  const control = useFieldControl(props)
  return <input data-slot="input" type={type} {...props} {...control} className={cn("flex h-11 w-full min-w-0 rounded-xl rounded-tr-[5px] border border-input bg-card px-3.5 py-2 text-base text-foreground shadow-xs transition-[border-color,box-shadow] placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background disabled:cursor-not-allowed disabled:opacity-50 aria-invalid:border-destructive aria-invalid:focus-visible:ring-destructive file:mr-3 file:border-0 file:bg-transparent file:text-sm file:font-semibold file:text-foreground md:text-sm motion-reduce:transition-none", className)} />
}
